/* 全局样式 */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Poppins', sans-serif;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    padding: 20px;
    color: #333;
}

.container {
    max-width: 1200px;
    margin: 0 auto;
}

/* 欢迎信息区域 */
.welcome-section {
    background: rgba(255, 255, 255, 0.95);
    border-radius: 20px;
    padding: 40px;
    margin-bottom: 30px;
    text-align: center;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
    animation: fadeIn 0.8s ease-out;
}

#welcomeMessage {
    font-size: 3.5rem;
    color: #667eea;
    margin-bottom: 10px;
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.1);
}

.welcome-subtitle {
    font-size: 1.2rem;
    color: #666;
    font-weight: 300;
}

/* 应用容器 */
.app-container {
    background: white;
    border-radius: 20px;
    padding: 30px;
    box-shadow: 0 15px 35px rgba(0, 0, 0, 0.1);
    animation: slideUp 0.6s ease-out;
}

/* 头部区域 */
.app-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 30px;
    padding-bottom: 20px;
    border-bottom: 2px solid #f0f0f0;
}

.header-content h1 {
    font-size: 2.5rem;
    color: #333;
    display: flex;
    align-items: center;
    gap: 15px;
}

.header-content h1 i {
    color: #667eea;
}

.app-description {
    color: #666;
    font-size: 1.1rem;
    margin-top: 5px;
}

.stats {
    display: flex;
    gap: 30px;
}

.stat-item {
    text-align: center;
    padding: 15px 25px;
    background: #f8f9fa;
    border-radius: 10px;
    min-width: 120px;
}

.stat-label {
    display: block;
    color: #666;
    font-size: 0.9rem;
    margin-bottom: 5px;
}

.stat-value {
    font-size: 2rem;
    font-weight: 700;
    color: #667eea;
}

/* 添加任务区域 */
.add-task-section {
    background: #f8f9fa;
    padding: 25px;
    border-radius: 15px;
    margin-bottom: 25px;
}

.input-group {
    display: flex;
    gap: 15px;
    margin-bottom: 15px;
}

#taskInput {
    flex: 1;
    padding: 15px 20px;
    border: 2px solid #e0e0e0;
    border-radius: 10px;
    font-size: 1rem;
    transition: all 0.3s;
}

#taskInput:focus {
    outline: none;
    border-color: #667eea;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

#prioritySelect {
    padding: 15px 20px;
    border: 2px solid #e0e0e0;
    border-radius: 10px;
    font-size: 1rem;
    background: white;
    min-width: 150px;
}

.btn-primary {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    border: none;
    padding: 15px 30px;
    border-radius: 10px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 10px;
    transition: all 0.3s;
}

.btn-primary:hover {
    transform: translateY(-2px);
    box-shadow: 0 5px 15px rgba(102, 126, 234, 0.3);
}

.input-hint {
    color: #666;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 8px;
}

/* 过滤和搜索区域 */
.filter-section {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 25px;
    padding: 20px;
    background: #f8f9fa;
    border-radius: 15px;
}

.filter-buttons {
    display: flex;
    gap: 10px;
}

.filter-btn {
    padding: 12px 24px;
    border: 2px solid #e0e0e0;
    background: white;
    border-radius: 10px;
    font-size: 0.95rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: all 0.3s;
}

.filter-btn:hover {
    border-color: #667eea;
    color: #667eea;
}

.filter-btn.active {
    background: #667eea;
    color: white;
    border-color: #667eea;
}

.search-box {
    position: relative;
    width: 300px;
}

.search-box i {
    position: absolute;
    left: 15px;
    top: 50%;
    transform: translateY(-50%);
    color: #666;
}

#searchInput {
    width: 100%;
    padding: 12px 20px 12px 45px;
    border: 2px solid #e0e0e0;
    border-radius: 10px;
    font-size: 0.95rem;
}

/* 任务列表区域 */
.tasks-container {
    background: #f8f9fa;
    border-radius: 15px;
    padding: 25px;
    margin-bottom: 25px;
}

.tasks-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 20px;
}

.tasks-header h2 {
    font-size: 1.8rem;
    color: #333;
    display: flex;
    align-items: center;
    gap: 10px;
}

.tasks-count {
    background: #667eea;
    color: white;
    padding: 8px 16px;
    border-radius: 20px;
    font-weight: 600;
}

.tasks-list {
    min-height: 300px;
}

.empty-state {
    text-align: center;
    padding: 60px 20px;
    color: #666;
}

.empty-state i {
    font-size: 4rem;
    color: #ddd;
    margin-bottom: 20px;
}

.empty-state h3 {
    font-size: 1.5rem;
    margin-bottom: 10px;
}

/* 任务项样式 */
.task-item {
    background: white;
    border-radius: 10px;
    padding: 20px;
    margin-bottom: 15px;
    display: flex;
    align-items: center;
    gap: 15px;
    transition: all 0.3s;
    animation: fadeIn 0.5s ease-out;
}

.task-item:hover {
    transform: translateX(5px);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.05);
}

.task-checkbox {
    width: 24px;
    height: 24px;
    cursor: pointer;
}

.task-content {
    flex: 1;
}

.task-title {
    font-size: 1.1rem;
    margin-bottom: 5px;
    transition: all 0.3s;
}

.task-item.completed .task-title {
    text-decoration: line-through;
    color: #999;
}

.task-meta {
    display: flex;
    gap: 15px;
    font-size: 0.9rem;
    color: #666;
}

.priority-badge {
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
}

.priority-low {
    background: #e8f5e9;
    color: #2e7d32;
}

.priority-medium {
    background: #fff3e0;
    color: #f57c00;
}

.priority-high {
    background: #ffebee;
    color: #c62828;
}

.task-actions {
    display: flex;
    gap: 10px;
}

.action-btn {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    border: none;
    background: #f8f9fa;
    color: #666;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s;
}

.action-btn:hover {
    background: #667eea;
    color: white;
}

/* 操作按钮区域 */
.action-buttons {
    display: flex;
    justify-content: center;
    gap: 15px;
    margin-bottom: 25px;
}

.btn-secondary {
    padding: 12px 24px;
    border: 2px solid #667eea;
    background: white;
    color: #667eea;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: all 0.3s;
}

.btn-secondary:hover {
    background: #667eea;
    color: white;
}

.btn-danger {
    padding: 12px 24px;
    border: 2px solid #dc3545;
    background: white;
    color: #dc3545;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    display: flex;
    align-items: center;
    gap: 8px;
    transition: all 0.3s;
}

.btn-danger:hover {
    background: #dc3545;
    color: white;
}

/* 底部信息 */
.app-footer {
    text-align: center;
    padding-top: 20px;
    border-top: 1px solid #f0f0f0;
    color: #666;
}

.footer-hint {
    font-size: 0.9rem;
    margin-top: 5px;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

/* 模态框样式 */
.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1000;
    align-items: center;
    justify-content: center;
}

.modal.active {
    display: flex;
    animation: fadeIn 0.3s ease-out;
}

.modal-content {
    background: white;
    border-radius: 15px;
    width: 90%;
    max-width: 500px;
    animation: slideUp 0.3s ease-out;
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px 30px;
    border-bottom: 1px solid #f0f0f0;
}

.modal-header h3 {
    font-size: 1.5rem;
    color: #333;
    display: flex;
    align-items: center;
    gap: 10px;
}

.close-modal {
    background: none;
    border: none;
    font-size: 1.8rem;
    color: #666;
    cursor: pointer;
    padding: 0;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.close-modal:hover {
    color: #333;
}

.modal-body {
    padding: 30px;
}

.form-group {
    margin-bottom: 20px;
}

.form-group label {
    display: block;
    margin-bottom: 8px;
    color: #333;
    font-weight: 500;
}

.form-group input,
.form-group select,
.form-group textarea {
    width: 100%;
    padding: 12px 15px;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    font-size: 1rem;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #667eea;
}

.form-hint {
    color: #666;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 8px;
    margin-top: 10px;
}

.modal-footer {
    padding: 20px 30px;
    border-top: 1px solid #f0f0f0;
    display: flex;
    justify-content: flex-end;
    gap: 15px;
}

/* 通知消息 */
.notification {
    position: fixed;
    top: 20px;
    right: 20px;
    background: #4caf50;
    color: white;
    padding: 15px 25px;
    border-radius: 10px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
    display: none;
    z-index: 1001;
    animation: slideInRight 0.3s ease-out;
}

.notification.active {
    display: block;
}

.notification-content {
    display: flex;
    align-items: center;
    gap: 10px;
}

/* 动画 */
@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes slideInRight {
    from {
        opacity: 0;
        transform: translateX(100%);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

/* 响应式设计 */
@media (max-width: 768px) {
    .app-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 20px;
    }

    .stats {
        width: 100%;
        justify-content: space-between;
    }

    .stat-item {
        flex: 1;
        min-width: auto;
    }

    .input-group {
        flex-direction: column;
    }

    .filter-section {
        flex-direction: column;
        gap: 15px;
    }

    .search-box {
        width: 100%;
    }

    .action-buttons {
        flex-wrap: wrap;
    }

    #welcomeMessage {
        font-size: 2.5rem;
    }
}

@media (max-width: 480px) {
    .container {
        padding: 10px;
    }

    .app-container {
        padding: 20px;
    }

    .header-content h1 {
        font-size: 2rem;
    }

    .stat-value {
        font-size: 1.5rem;
    }

    .task-item {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .task-actions {
        align-self: flex-end;
    }
}

// TodoList 应用主逻辑
class TodoApp {
    constructor() {
        this.tasks = [];
        this.currentFilter = 'all';
        this.currentSearch = '';
        this.editingTaskId = null;

        // 初始化DOM元素引用
        this.initializeElements();
        // 初始化事件监听
        this.initializeEventListeners();
        // 加载保存的任务
        this.loadTasks();
        // 更新UI
        this.updateUI();
    }

    // 初始化DOM元素引用
    initializeElements() {
        // 输入和按钮
        this.taskInput = document.getElementById('taskInput');
        this.prioritySelect = document.getElementById('prioritySelect');
        this.addTaskBtn = document.getElementById('addTaskBtn');
        this.searchInput = document.getElementById('searchInput');

        // 过滤按钮
        this.filterButtons = document.querySelectorAll('.filter-btn');

        // 统计元素
        this.totalTasksElement = document.getElementById('totalTasks');
        this.completedTasksElement = document.getElementById('completedTasks');
        this.pendingTasksElement = document.getElementById('pendingTasks');
        this.tasksCountElement = document.getElementById('tasksCount');

        // 任务列表容器
        this.tasksListElement = document.getElementById('tasksList');

        // 操作按钮
        this.clearCompletedBtn = document.getElementById('clearCompletedBtn');
        this.exportTasksBtn = document.getElementById('exportTasksBtn');
        this.importTasksBtn = document.getElementById('importTasksBtn');
        this.clearAllBtn = document.getElementById('clearAllBtn');

        // 模态框相关
        this.editModal = document.getElementById('editModal');
        this.importModal = document.getElementById('importModal');
        this.confirmModal = document.getElementById('confirmModal');
        this.notification = document.getElementById('notification');

        // 编辑表单元素
        this.editTaskTitle = document.getElementById('editTaskTitle');
        this.editPrioritySelect = document.getElementById('editPrioritySelect');
        this.saveEditBtn = document.getElementById('saveEditBtn');

        // 导入表单元素
        this.importText = document.getElementById('importText');
        this.confirmImportBtn = document.getElementById('confirmImportBtn');

        // 确认对话框元素
        this.confirmMessage = document.getElementById('confirmMessage');
        this.confirmActionBtn = document.getElementById('confirmActionBtn');

        // 通知消息元素
        this.notificationMessage = document.getElementById('notificationMessage');

        // 关闭模态框按钮
        this.closeModalButtons = document.querySelectorAll('.close-modal');
    }

    // 初始化事件监听
    initializeEventListeners() {
        // 添加任务
        this.addTaskBtn.addEventListener('click', () => this.addTask());
        this.taskInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') {
                this.addTask();
            }
        });

        // 搜索任务
        this.searchInput.addEventListener('input', (e) => {
            this.currentSearch = e.target.value.toLowerCase();
            this.updateUI();
        });

        // 过滤任务
        this.filterButtons.forEach(button => {
            button.addEventListener('click', (e) => {
                const filter = e.target.dataset.filter;
                this.setFilter(filter);
            });
        });

        // 操作按钮
        this.clearCompletedBtn.addEventListener('click', () => this.clearCompletedTasks());
        this.exportTasksBtn.addEventListener('click', () => this.exportTasks());
        this.importTasksBtn.addEventListener('click', () => this.showImportModal());
        this.clearAllBtn.addEventListener('click', () => this.confirmClearAll());

        // 编辑任务
        this.saveEditBtn.addEventListener('click', () => this.saveTaskEdit());

        // 导入任务
        this.confirmImportBtn.addEventListener('click', () => this.importTasks());

        // 确认操作
        this.confirmActionBtn.addEventListener('click', () => this.executeConfirmedAction());

        // 关闭模态框
        this.closeModalButtons.forEach(button => {
            button.addEventListener('click', () => this.closeAllModals());
        });

        // 点击模态框背景关闭
        [this.editModal, this.importModal, this.confirmModal].forEach(modal => {
            modal.addEventListener('click', (e) => {
                if (e.target === modal) {
                    this.closeAllModals();
                }
            });
        });

        // 键盘事件：ESC关闭模态框
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape') {
                this.closeAllModals();
            }
        });
    }

    // 添加新任务
    addTask() {
        const title = this.taskInput.value.trim();
        if (!title) {
            this.showNotification('请输入任务内容', 'error');
            return;
        }

        const task = {
            id: Date.now(),
            title: title,
            priority: this.prioritySelect.value,
            completed: false,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
        };

        this.tasks.unshift(task); // 添加到开头
        this.saveTasks();
        this.updateUI();

        // 清空输入框
        this.taskInput.value = '';
        this.taskInput.focus();

        this.showNotification('任务添加成功');
    }

    // 切换任务完成状态
    toggleTaskCompletion(taskId) {
        const task = this.tasks.find(t => t.id === taskId);
        if (task) {
            task.completed = !task.completed;
            task.updatedAt = new Date().toISOString();
            this.saveTasks();
            this.updateUI();

            const message = task.completed ? '任务标记为已完成' : '任务标记为待完成';
            this.showNotification(message);
        }
    }

    // 编辑任务
    editTask(taskId) {
        const task = this.tasks.find(t => t.id === taskId);
        if (task) {
            this.editingTaskId = taskId;
            this.editTaskTitle.value = task.title;
            this.editPrioritySelect.value = task.priority;
            this.editModal.classList.add('active');
        }
    }

    // 保存任务编辑
    saveTaskEdit() {
        if (!this.editingTaskId) return;

        const title = this.editTaskTitle.value.trim();
        if (!title) {
            this.showNotification('请输入任务内容', 'error');
            return;
        }

        const task = this.tasks.find(t => t.id === this.editingTaskId);
        if (task) {
            task.title = title;
            task.priority = this.editPrioritySelect.value;
            task.updatedAt = new Date().toISOString();
            this.saveTasks();
            this.updateUI();
            this.closeAllModals();
            this.showNotification('任务编辑成功');
        }
    }

    // 删除任务
    deleteTask(taskId) {
        this.tasks = this.tasks.filter(task => task.id !== taskId);
        this.saveTasks();
        this.updateUI();
        this.showNotification('任务删除成功');
    }

    // 清除已完成任务
    clearCompletedTasks() {
        const completedCount = this.tasks.filter(task => task.completed).length;
        if (completedCount === 0) {
            this.showNotification('没有已完成的任务', 'info');
            return;
        }

        this.tasks = this.tasks.filter(task => !task.completed);
        this.saveTasks();
        this.updateUI();
        this.showNotification(`已清除 ${completedCount} 个已完成任务`);
    }

    // 清空所有任务
    clearAllTasks() {
        if (this.tasks.length === 0) {
            this.showNotification('没有任务可清除', 'info');
            return;
        }

        this.tasks = [];
        this.saveTasks();
        this.updateUI();
        this.showNotification('所有任务已清空');
    }

    // 导出任务
    exportTasks() {
        const exportData = {
            version: '1.0',
            exportDate: new Date().toISOString(),
            tasks: this.tasks
        };

        const jsonString = JSON.stringify(exportData, null, 2);
        const blob = new Blob([jsonString], { type: 'application/json' });
        const url = URL.createObjectURL(blob);

        const a = document.createElement('a');
        a.href = url;
        a.download = `todolist-backup-${new Date().toISOString().split('T')[0]}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);

        this.showNotification('任务导出成功');
    }

    // 显示导入模态框
    showImportModal() {
        this.importText.value = '';
        this.importModal.classList.add('active');
    }

    // 导入任务
    importTasks() {
        const importText = this.importText.value.trim();
        if (!importText) {
            this.showNotification('请输入要导入的数据', 'error');
            return;
        }

        try {
            const importData = JSON.parse(importText);

            // 验证导入数据格式
            if (!importData.tasks || !Array.isArray(importData.tasks)) {
                throw new Error('导入数据格式不正确');
            }

            // 验证每个任务的基本结构
            const validTasks = importData.tasks.filter(task => 
                task.id && task.title && typeof task.completed === 'boolean'
            );

            if (validTasks.length === 0) {
                throw new Error('没有有效的任务数据');
            }

            this.tasks = validTasks;
            this.saveTasks();
            this.updateUI();
            this.closeAllModals();
            this.showNotification(`成功导入 ${validTasks.length} 个任务`);

        } catch (error) {
            this.showNotification(`导入失败: ${error.message}`, 'error');
        }
    }

    // 设置过滤条件
    setFilter(filter) {
        this.currentFilter = filter;

        // 更新过滤按钮状态
        this.filterButtons.forEach(button => {
            if (button.dataset.filter === filter) {
                button.classList.add('active');
            } else {
                button.classList.remove('active');
            }
        });

        this.updateUI();
    }

    // 获取过滤后的任务
    getFilteredTasks() {
        let filteredTasks = this.tasks;

        // 应用状态过滤
        switch (this.currentFilter) {
            case 'pending':
                filteredTasks = filteredTasks.filter(task => !task.completed);
                break;
            case 'completed':
                filteredTasks = filteredTasks.filter(task => task.completed);
                break;
            // 'all' 不进行过滤
        }

        // 应用搜索过滤
        if (this.currentSearch) {
            filteredTasks = filteredTasks.filter(task => 
                task.title.toLowerCase().includes(this.currentSearch)
            );
        }

        return filteredTasks;
    }

    // 更新UI
    updateUI() {
        const filteredTasks = this.getFilteredTasks();

        // 更新统计信息
        const totalTasks = this.tasks.length;
        const completedTasks = this.tasks.filter(task => task.completed).length;
        const pendingTasks = totalTasks - completedTasks;

        this.totalTasksElement.textContent = totalTasks;
        this.completedTasksElement.textContent = completedTasks;
        this.pendingTasksElement.textContent = pendingTasks;
        this.tasksCountElement.textContent = `${filteredTasks.length} 个任务`;

        // 更新任务列表
        this.renderTasks(filteredTasks);
    }

    // 渲染任务列表
    renderTasks(tasks) {
        if (tasks.length === 0) {
            this.tasksListElement.innerHTML = `
                <div class="empty-state">
                    <i class="fas fa-clipboard-list"></i>
                    <h3>暂无任务</h3>
                    <p>${this.currentSearch ? '没有找到匹配的任务' : '添加您的第一个任务开始管理'}</p>
                </div>
            `;
            return;
        }

        this.tasksListElement.innerHTML = tasks.map(task => `
            <div class="task-item ${task.completed ? 'completed' : ''}" data-task-id="${task.id}">
                <input type="checkbox" class="task-checkbox" 
                       ${task.completed ? 'checked' : ''}
                       onclick="todoApp.toggleTaskCompletion(${task.id})">

                <div class="task-content">
                    <div class="task-title">${this.escapeHtml(task.title)}</div>
                    <div class="task-meta">
                        <span class="priority-badge priority-${task.priority}">
                            ${this.getPriorityText(task.priority)}
                        </span>
                        <span class="task-date">
                            <i class="far fa-calendar"></i>
                            ${new Date(task.createdAt).toLocaleDateString()}
                        </span>
                    </div>
                </div>

                <div class="task-actions">
                    <button class="action-btn edit-btn" onclick="todoApp.editTask(${task.id})">
                        <i class="fas fa-edit"></i>
                    </button>
                    <button class="action-btn delete-btn" onclick="todoApp.deleteTask(${task.id})">
                        <i class="fas fa-trash-alt"></i>
                    </button>
                </div>
            </div>
        `).join('');
    }

    // 获取优先级文本
    getPriorityText(priority) {
        const priorityMap = {
            'low': '低优先级',
            'medium': '中优先级',
            'high': '高优先级'
        };
        return priorityMap[priority] || '未知';
    }

    // 转义HTML
    escapeHtml(text) {
        const div = document.createElement('div');
        div.textContent = text;
        return div.innerHTML;
    }

    // 保存任务到本地存储
    saveTasks() {
        try {
            localStorage.setItem('todolist_tasks', JSON.stringify(this.tasks));
        } catch (error) {
            console.error('保存任务失败:', error);
            this.showNotification('保存任务失败，请检查存储空间', 'error');
        }
    }

    // 从本地存储加载任务
    loadTasks() {
        try {
            const savedTasks = localStorage.getItem('todolist_tasks');
            if (savedTasks) {
                this.tasks = JSON.parse(savedTasks);
            }
        } catch (error) {
            console.error('加载任务失败:', error);
            this.tasks = [];
        }
    }

    // 显示确认对话框
    confirmClearAll() {
        if (this.tasks.length === 0) {
            this.showNotification('没有任务可清除', 'info');
            return;
        }

        this.confirmMessage.textContent = `您确定要清空所有 ${this.tasks.length} 个任务吗？此操作不可撤销。`;
        this.confirmActionBtn.onclick = () => this.clearAllTasks();
        this.confirmModal.classList.add('active');
    }

    // 执行确认的操作
    executeConfirmedAction() {
        // 这个函数现在只用于确认对话框的回调
        this.closeAllModals();
    }

    // 关闭所有模态框
    closeAllModals() {
        this.editModal.classList.remove('active');
        this.importModal.classList.remove('active');
        this.confirmModal.classList.remove('active');
        this.editingTaskId = null;
    }

    // 显示通知消息
    showNotification(message, type = 'success') {
        this.notificationMessage.textContent = message;

        // 根据类型设置样式
        const notificationContent = this.notification.querySelector('.notification-content');
        const icon = notificationContent.querySelector('i');

        switch (type) {
            case 'error':
                this.notification.style.background = '#dc3545';
                icon.className = 'fas fa-exclamation-circle';
                break;
            case 'info':
                this.notification.style.background = '#17a2b8';
                icon.className = 'fas fa-info-circle';
                break;
            default:
                this.notification.style.background = '#4caf50';
                icon.className = 'fas fa-check-circle';
        }

        this.notification.classList.add('active');

        // 3秒后自动隐藏
        setTimeout(() => {
            this.notification.classList.remove('active');
        }, 3000);
    }
}

